using DownloadManager.Core;
using System.Diagnostics;
using System.Net.NetworkInformation;
using System.Text.Json;
using System.Security.Cryptography;

var root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);var fixtures=Path.GetFullPath(args[1]);var ffmpeg=Path.GetFullPath(args[2]);var probe=Path.Combine(Path.GetDirectoryName(ffmpeg)!,"ffprobe.exe");var assertions=0;
void Check(bool value,string key){assertions++;if(!value)throw new Exception(key);}
async Task Until(Func<Task<bool>> condition){var end=DateTime.UtcNow.AddSeconds(45);while(!await condition()){if(DateTime.UtcNow>end)throw new TimeoutException();await Task.Delay(20);}}
async Task<string[]> Streams(string path){var start=new ProcessStartInfo(probe){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};foreach(var arg in new[]{"-v","error","-show_entries","stream=codec_type","-of","json",path})start.ArgumentList.Add(arg);using var process=Process.Start(start)!;var output=await process.StandardOutput.ReadToEndAsync();await process.WaitForExitAsync();Check(process.ExitCode==0,"ffprobe_failed");using var json=JsonDocument.Parse(output);return json.RootElement.GetProperty("streams").EnumerateArray().Select(s=>s.GetProperty("codec_type").GetString()!).ToArray();}
await using var server=new FixtureServer{MediaRoot=fixtures};await server.StartAsync();var port=server.Port;
try{
 await using(var engine=new DownloadEngine(Path.Combine(root,"engine"))){
  engine.Configure(new(){MaxConnections=8,RetryCount=0,MediaMuxerPath=ffmpeg,Network=new(){Mode=ProxySelection.Direct},BytesPerSecond=32768});
  var hls=await engine.AddAsync(server.Url("media/master.m3u8"),Path.Combine(root,"files"));Check(hls.FileName.EndsWith(".mp4",StringComparison.Ordinal),"media_suggested_extension");
  await Until(async()=>{var job=(await engine.SnapshotAsync()).Single();return job.MediaCompletedParts>0||job.State==DownloadState.Failed;});await engine.PauseAsync(hls.Id);var paused=(await engine.SnapshotAsync()).Single();Check(paused.State==DownloadState.Paused&&paused.MediaCompletedParts>0,"hls_pause_checkpoint");
  engine.Configure(engine.CurrentSettings with{BytesPerSecond=0});await engine.StartAsync(hls.Id);await Until(async()=>(await engine.SnapshotAsync()).Single().State is DownloadState.Completed or DownloadState.Failed);var result=(await engine.SnapshotAsync()).Single();Console.WriteLine(JsonSerializer.Serialize(new{result.State,result.ErrorKey,result.ErrorDetail}));Check(result.State==DownloadState.Completed,"hls_mux_failed");
  var streams=await Streams(result.FinalPath);Check(streams.Contains("video")&&streams.Contains("audio"),"hls_audio_video_not_merged");Check(server.Captured.Any(r=>r.Path.StartsWith("media/",StringComparison.Ordinal)&&r.Headers.ContainsKey("If-None-Match")),"hls_resume_not_validated");Check(!Directory.Exists(Path.Combine(Path.GetDirectoryName(result.PartialPath)!,".dm-"+result.Id+".media")),"media_cache_not_removed");
  var dash=await engine.AddAsync(server.Url("media/index.mpd"),Path.Combine(root,"files"));await Until(async()=>(await engine.SnapshotAsync()).Single(j=>j.Id==dash.Id).State is DownloadState.Completed or DownloadState.Failed);result=(await engine.SnapshotAsync()).Single(j=>j.Id==dash.Id);Console.WriteLine(JsonSerializer.Serialize(new{result.State,result.ErrorKey,result.ErrorDetail}));Check(result.State==DownloadState.Completed,"dash_mux_failed");streams=await Streams(result.FinalPath);Check(streams.Contains("video")&&streams.Contains("audio"),"dash_audio_video_not_merged");
 }
 // Encrypt local TS fixtures with AES-128; only the fixture knows the plaintext key.
 var key=Enumerable.Range(0,16).Select(i=>(byte)i).ToArray();await File.WriteAllBytesAsync(Path.Combine(fixtures,"key.bin"),key);var playlist=new List<string>{"#EXTM3U","#EXT-X-VERSION:3","#EXT-X-TARGETDURATION:1","#EXT-X-MEDIA-SEQUENCE:5","#EXT-X-KEY:METHOD=AES-128,URI=\"key.bin\""};
 for(var i=0;i<3;i++){using var aes=Aes.Create();aes.Key=key;var iv=new byte[16];System.Buffers.Binary.BinaryPrimitives.WriteInt64BigEndian(iv.AsSpan(8),i+5);aes.IV=iv;var plain=await File.ReadAllBytesAsync(Path.Combine(fixtures,$"video-{i:D2}.ts"));var encrypted=aes.EncryptCbc(plain,iv,PaddingMode.PKCS7);await File.WriteAllBytesAsync(Path.Combine(fixtures,$"encrypted-{i}.ts"),encrypted);playlist.Add("#EXTINF:1.0,");playlist.Add($"encrypted-{i}.ts");}playlist.Add("#EXT-X-ENDLIST");await File.WriteAllLinesAsync(Path.Combine(fixtures,"encrypted.m3u8"),playlist);
 await using(var engine=new DownloadEngine(Path.Combine(root,"encrypted-engine"))){engine.Configure(new(){MediaMuxerPath=ffmpeg,RetryCount=0});var encrypted=await engine.AddAsync(server.Url("media/encrypted.m3u8"),Path.Combine(root,"files"));await Until(async()=>(await engine.SnapshotAsync()).Single().State is DownloadState.Completed or DownloadState.Failed);var result=(await engine.SnapshotAsync()).Single();Check(result.State==DownloadState.Completed,"hls_aes128_failed");Check((await Streams(result.FinalPath)).Contains("video"),"decrypted_video_missing");}
 await using(var engine=new DownloadEngine(Path.Combine(root,"quota-engine"))){engine.Configure(new(){MediaMuxerPath=ffmpeg,RetryCount=0,Quota=new(true,4096,1)});var file=await engine.AddAsync(server.Url("media/video.m3u8"),Path.Combine(root,"files"));await Until(async()=>(await engine.SnapshotAsync()).Single().PhaseKey=="native.waiting_quota");await engine.PauseAsync(file.Id);Check((await engine.SnapshotAsync()).Single().TransferredBytes<=4096,"media_quota_exceeded");engine.Configure(engine.CurrentSettings with{Quota=new()});await engine.StartAsync(file.Id);await Until(async()=>(await engine.SnapshotAsync()).Single().State is DownloadState.Completed or DownloadState.Failed);Check((await engine.SnapshotAsync()).Single().State==DownloadState.Completed,"media_quota_resume_failed");}
 var live="#EXTM3U\n#EXTINF:1,\nsegment.ts";try{await AdaptiveManifest.ReadAsync(new("https://fixture.test/live.m3u8"),uri=>Task.FromResult(new MediaDocument(live,uri)));throw new Exception("unbounded_live_accepted");}catch(InvalidDataException){assertions++;}
 Console.WriteLine($"PASS {assertions} adaptive-media assertions: HLS, separate audio, DASH, AES-128, validated resume, local mux, quota and cancellation.");
}finally{await server.DisposeAsync();}
Check(!IPGlobalProperties.GetIPGlobalProperties().GetActiveTcpListeners().Any(p=>p.Port==port),"media_listener_leaked");Console.WriteLine($"Temporary media fixture port {port} closed.");
